using System;
using System.Linq;
using Microsoft.Build.Logging.StructuredLogger;

class Program
{
    static void Main(string[] args)
    {
        var build = BinaryLog.ReadBuild(args[0]);

        // Collect all errors
        var errors = build.FindChildrenRecursive<Error>();
        Console.WriteLine($"=== TOTAL ERRORS: {errors.Count} ===\n");

        foreach (var error in errors)
        {
            // Walk up to find the project
            var node = (BaseNode)error;
            string project = "unknown";
            while (node != null)
            {
                if (node is Project p)
                {
                    project = p.Name;
                    break;
                }
                node = node.Parent as BaseNode;
            }

            Console.WriteLine($"PROJECT: {project}");
            Console.WriteLine($"CODE: {error.Code}");
            Console.WriteLine($"FILE: {error.File}");
            Console.WriteLine($"LINE: {error.LineNumber}");
            Console.WriteLine($"MESSAGE: {error.Text}");
            Console.WriteLine("---");
        }

        // Also show warnings that might be relevant
        var warnings = build.FindChildrenRecursive<Warning>();
        Console.WriteLine($"\n=== TOTAL WARNINGS: {warnings.Count} ===\n");
        foreach (var w in warnings)
        {
            var node2 = (BaseNode)w;
            string proj2 = "unknown";
            while (node2 != null)
            {
                if (node2 is Project p2)
                {
                    proj2 = p2.Name;
                    break;
                }
                node2 = node2.Parent as BaseNode;
            }
            Console.WriteLine($"PROJECT: {proj2}  CODE: {w.Code}  MESSAGE: {w.Text}");
        }
    }
}
