using System;
using System.Linq;
using System.Collections.Generic;
using Microsoft.Build.Logging.StructuredLogger;

class Program2
{
    static void Main(string[] args)
    {
        var build = BinaryLog.ReadBuild(args[0]);

        // Find all projects and their references
        var projects = build.FindChildrenRecursive<Project>();
        Console.WriteLine("=== PROJECTS IN BUILD ===");
        foreach (var p in projects)
        {
            Console.WriteLine($"  {p.Name} -> {p.ProjectFile}");
        }

        // Check for project dependency failures
        Console.WriteLine("\n=== PROJECT BUILD RESULTS ===");
        foreach (var p in projects)
        {
            Console.WriteLine($"  {p.Name}: Succeeded={p.Succeeded}");
        }

        // Extract source file contents from binlog if embedded
        Console.WriteLine("\n=== LOOKING FOR EMBEDDED FILES ===");
        var sourceFiles = build.FindChildrenRecursive<SourceFile>();
        Console.WriteLine($"Found {sourceFiles.Count} embedded source files");
        foreach (var sf in sourceFiles)
        {
            Console.WriteLine($"  {sf.Name}");
        }

        // Try to find the project file content or PackageReference items
        var items = build.FindChildrenRecursive<Item>();
        var pkgRefs = items.Where(i => i.Name?.Contains("PackageReference") == true || 
                                       i.Parent?.ToString()?.Contains("PackageReference") == true).ToList();
        Console.WriteLine($"\n=== PACKAGE REFERENCES ({pkgRefs.Count}) ===");
        foreach (var item in pkgRefs)
        {
            var node = (BaseNode)item;
            string proj = "unknown";
            while (node != null)
            {
                if (node is Project pp) { proj = pp.Name; break; }
                node = node.Parent as BaseNode;
            }
            Console.WriteLine($"  [{proj}] {item.Text}");
        }

        // Look for AddItem with PackageReference
        var folders = build.FindChildrenRecursive<Folder>();
        foreach (var f in folders)
        {
            if (f.Name?.Contains("PackageReference") == true)
            {
                Console.WriteLine($"\n=== FOLDER: {f.Name} ===");
                foreach (var child in f.Children)
                    Console.WriteLine($"  {child}");
            }
        }
    }
}
