using System;
using System.Linq;
using System.Collections.Generic;
using Microsoft.Build.Logging.StructuredLogger;

class Program
{
    static void Main(string[] args)
    {
        var build = BinaryLog.ReadBuild(args[0]);

        var projects = build.FindChildrenRecursive<Project>();
        Console.WriteLine("=== PROJECTS IN BUILD ===");
        foreach (var p in projects)
            Console.WriteLine($"  {p.Name} -> {p.ProjectFile}");

        // Look at all named nodes for PackageReference
        Console.WriteLine("\n=== SEARCHING FOR PACKAGEREFERENCE ===");
        var allNodes = build.FindChildrenRecursive<NamedNode>();
        foreach (var n in allNodes)
        {
            if (n.Name?.Contains("PackageReference") == true)
                Console.WriteLine($"  [{n.GetType().Name}] {n.Name}: {n.Text}");
        }

        // Look for items
        Console.WriteLine("\n=== ALL ITEMS CONTAINING 'Newtonsoft' or 'PackageRef' ===");
        var items = build.FindChildrenRecursive<Item>();
        foreach (var item in items)
        {
            string txt = item.Text ?? "";
            string name = item.Name ?? "";
            if (txt.Contains("Newtonsoft") || txt.Contains("PackageRef") || name.Contains("PackageRef"))
                Console.WriteLine($"  [{item.GetType().Name}] Name={name} Text={txt}");
        }

        // Find all AddItem/RemoveItem related
        Console.WriteLine("\n=== ADDITEM GROUPS ===");
        var addItems = build.FindChildrenRecursive<AddItem>();
        foreach (var ai in addItems)
        {
            Console.WriteLine($"  AddItem: {ai.Name} ({ai.Children.Count} children)");
            foreach (var c in ai.Children.Take(5))
                Console.WriteLine($"    -> {c}");
        }

        // Show the embedded source file content
        Console.WriteLine("\n=== EMBEDDED SOURCE FILES ===");
        var sourceFiles = build.FindChildrenRecursive<SourceFile>();
        foreach (var sf in sourceFiles)
        {
            Console.WriteLine($"\n--- {sf.Name} ---");
            // SourceFile might have text
        }

        // Check if we can extract .csproj content via SourceFilesCollector or similar
        var allTexts = build.FindChildrenRecursive<TextNode>();
        int count = 0;
        foreach (var t in allTexts)
        {
            if (t.Text?.Contains("PackageReference") == true || t.Text?.Contains("Newtonsoft") == true)
            {
                Console.WriteLine($"\n=== TEXT NODE with PackageReference/Newtonsoft ===");
                Console.WriteLine(t.Text?.Substring(0, Math.Min(500, t.Text.Length)));
                if (++count > 10) break;
            }
        }
    }
}
