using System;
using System.Linq;
using Microsoft.Build.Logging.StructuredLogger;

class Program
{
    static void Main(string[] args)
    {
        var build = BinaryLog.ReadBuild(args[0]);

        var projects = build.FindChildrenRecursive<Project>();
        Console.WriteLine("=== PROJECTS ===");
        foreach (var p in projects)
            Console.WriteLine($"  {p.Name} -> {p.ProjectFile}");

        Console.WriteLine("\n=== ADDITEM: PackageReference ===");
        var addItems = build.FindChildrenRecursive<AddItem>();
        foreach (var ai in addItems)
        {
            if (ai.Name == "PackageReference")
            {
                var node = (BaseNode)ai;
                string proj = "?";
                while (node != null) { if (node is Project pp) { proj = pp.Name; break; } node = node.Parent as BaseNode; }
                foreach (var c in ai.Children)
                    Console.WriteLine($"  [{proj}] {c}");
            }
        }

        Console.WriteLine("\n=== ERRORS ===");
        var errors = build.FindChildrenRecursive<Error>();
        foreach (var e in errors)
        {
            var node = (BaseNode)e;
            string proj = "?";
            while (node != null) { if (node is Project pp) { proj = pp.Name; break; } node = node.Parent as BaseNode; }
            Console.WriteLine($"  [{proj}] {e.Code}: {e.Text}");
            Console.WriteLine($"    File: {e.File}:{e.LineNumber}");
        }

        // Check if any project failed due to dependency
        Console.WriteLine("\n=== MESSAGES about 'not build' or 'dependency' ===");
        var msgs = build.FindChildrenRecursive<Message>();
        int cnt = 0;
        foreach (var m in msgs)
        {
            var t = m.Text ?? "";
            if (t.Contains("not build") || t.Contains("dependency") || t.Contains("did not build") || t.Contains("previously failed"))
            {
                Console.WriteLine($"  {t.Substring(0, Math.Min(200, t.Length))}");
                if (++cnt > 10) break;
            }
        }
    }
}
