            Console.WriteLine($"  {f.SourceFilePath}");

        // Try to get source content - look for the .csproj and .cs files
        Console.WriteLine("\n=== Services.csproj content (if embedded) ===");
        foreach (var f in files)
        {
            if (f.SourceFilePath?.Contains("Services") == true)
            {
                Console.WriteLine($"  Path: {f.SourceFilePath}");
                Console.WriteLine($"  Content length: {f.Text?.Length}");
                Console.WriteLine(f.Text);
            }
        }

        // Look at all AddItem groups for any package info
        Console.WriteLine("\n=== ALL ADDITEM NAMES ===");
        var addItems = build.FindChildrenRecursive<AddItem>();
        var names = addItems.Select(a => a.Name).Distinct().OrderBy(n => n);
        foreach (var n in names)
            Console.WriteLine($"  {n}");

        // Check for NuGet restore messages
        Console.WriteLine("\n=== NUGET / RESTORE MESSAGES ===");
        var msgs = build.FindChildrenRecursive<Message>();
        int cnt = 0;
        foreach (var m in msgs)
        {
            var t = m.Text ?? "";
            if (t.Contains("NuGet") || t.Contains("nuget") || t.Contains("Restore") || t.Contains("restore"))
            {
                if (t.Contains("Newtonsoft") || t.Contains("PackageReference") || t.Contains("error") || t.Contains("warning") || t.Contains("NU"))
                {
                    Console.WriteLine($"  {t.Substring(0, Math.Min(300, t.Length))}");
