using System;
using System.Linq;
using Microsoft.Build.Logging.StructuredLogger;

class Program
{
    static void Main(string[] args)
    {
        var build = BinaryLog.ReadBuild(args[0]);

        // Get the source file paths from Compile items
        Console.WriteLine("=== COMPILE ITEMS ===");
        var addItems = build.FindChildrenRecursive<AddItem>();
        foreach (var ai in addItems)
        {
            if (ai.Name == "Compile")
            {
                var node = (BaseNode)ai;
                string proj = "?";
                while (node != null) { if (node is Project pp) { proj = pp.Name; break; } node = node.Parent as BaseNode; }
                foreach (var c in ai.Children)
                    Console.WriteLine($"  [{proj}] {c}");
            }
        }

        // Project dependency chain
        Console.WriteLine("\n=== PROJECT REFERENCES ===");
        foreach (var ai in addItems)
        {
            if (ai.Name == "ProjectReference")
            {
                var node = (BaseNode)ai;
                string proj = "?";
                while (node != null) { if (node is Project pp) { proj = pp.Name; break; } node = node.Parent as BaseNode; }
                foreach (var c in ai.Children)
                    Console.WriteLine($"  [{proj}] -> {c}");
            }
        }

        // Check for resolved references (to see what DLLs Services.csproj has)
        Console.WriteLine("\n=== RESOLVED REFERENCES FOR SERVICES (sample) ===");
        foreach (var ai in addItems)
        {
            if (ai.Name == "ReferencePath" || ai.Name == "Reference")
            {
                var node = (BaseNode)ai;
                string proj = "?";
                while (node != null) { if (node is Project pp) { proj = pp.Name; break; } node = node.Parent as BaseNode; }
                if (proj.Contains("Services"))
                {
                    foreach (var c in ai.Children)
                    {
                        var str = c.ToString();
                        if (str.Contains("Newtonsoft") || str.Contains("Json"))
                            Console.WriteLine($"  [{proj}] {ai.Name}: {str}");
                    }
                }
            }
        }

        // Get target frameworks
        Console.WriteLine("\n=== TARGET FRAMEWORK PROPERTIES ===");
        var props = build.FindChildrenRecursive<Property>();
        foreach (var p in props)
        {
            if (p.Name == "TargetFramework" || p.Name == "TargetFrameworks")
            {
                var node = (BaseNode)p;
                string proj = "?";
                while (node != null) { if (node is Project pp) { proj = pp.Name; break; } node = node.Parent as BaseNode; }
                Console.WriteLine($"  [{proj}] {p.Name} = {p.Value}");
            }
        }
    }
}
